// Vanilla Three.js example - the core library without React
import * as THREE from 'three';

// Step 1: Create a Scene
// The scene is like a container that holds all your 3D objects
const scene = new THREE.Scene();

// Step 2: Create a Camera
// PerspectiveCamera mimics how the human eye sees (perspective projection)
// Parameters: (field of view, aspect ratio, near plane, far plane)
const camera = new THREE.PerspectiveCamera(
  75, // Field of view (degrees) - wider = more visible
  window.innerWidth / window.innerHeight, // Aspect ratio (width/height)
  0.1, // Near clipping plane (objects closer than this won't render)
  1000 // Far clipping plane (objects farther than this won't render)
);

// Step 3: Create a Renderer
// WebGLRenderer uses WebGL to draw the 3D scene on a canvas
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
// Append the renderer's canvas (the drawing surface) to the page
document.body.appendChild(renderer.domElement);

// Step 4: Create Geometry
// BoxGeometry defines the shape - a rectangular box/cube
// Parameters: (width, height, depth)
const geometry = new THREE.BoxGeometry(1, 1, 1);

// Step 5: Create Material
// MeshStandardMaterial defines how the surface looks and responds to light
// This material responds to lighting in the scene
const material = new THREE.MeshStandardMaterial({ 
  color: 0x3b82f6, // Hex color (blue)
  metalness: 0.7, // How metallic (0-1)
  roughness: 0.3  // How smooth (0-1)
});

// Step 6: Create a Mesh
// A mesh combines geometry (shape) + material (appearance)
const cube = new THREE.Mesh(geometry, material);
scene.add(cube); // Add the cube to the scene

// Step 7: Add Lighting
// Objects need light to be visible (unless using MeshBasicMaterial)
const ambientLight = new THREE.AmbientLight(0xffffff, 0.5); // Soft overall light
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
directionalLight.position.set(5, 5, 5); // Position the light
scene.add(directionalLight);

// Step 8: Position the Camera
// Move camera back so we can see the cube (default is at origin [0,0,0])
camera.position.z = 5;

// Step 9: Animation Loop
// requestAnimationFrame creates a smooth 60fps animation loop
function animate() {
  requestAnimationFrame(animate); // Schedule next frame

  // Rotate the cube every frame
  cube.rotation.x += 0.01; // Rotate around X axis
  cube.rotation.y += 0.01; // Rotate around Y axis

  // Render the scene from the camera's perspective
  renderer.render(scene, camera);
}

// Start the animation
animate();

