// Component function - the absolute basics of R3F
function R3FBasicsScene() {
  return (
    <mesh>
      {/* Geometry defines the shape
          boxGeometry creates a rectangular box/cube
          args: [width, height, depth] - dimensions of the box */}
      <boxGeometry args={[2, 2, 2]} />

      {/* Material defines how the surface looks
          meshStandardMaterial responds to lighting in the scene
