// Geometries are built-in components provided by React Three Fiber
// They come from Three.js and are available directly in R3F
// No need to import them - just use them as JSX components

// Component function - demonstrates different built-in geometry types
function R3FGeometriesScene() {
  return (
    // group is like a React Fragment but for 3D objects
    // It allows you to group multiple meshes together
    <group>
      {/* BoxGeometry - rectangular prism (built-in from Three.js)
          position: [-2.5, 0, 0] = 2.5 units to the left
          args: [width, height, depth] */}
      <mesh position={[-2.5, 0, 0]}>
        <boxGeometry args={[1, 1.5, 0.5]} />
        <meshStandardMaterial color="#3b82f6" />
      </mesh>

      {/* SphereGeometry - 3D ball (built-in from Three.js)
          position: [-0.8, 0, 0] = slightly to the left
          args: [radius, widthSegments, heightSegments]
          radius: 0.7 = sphere with radius 0.7 units
          widthSegments: 32 = 32 divisions horizontally (smooth)
          heightSegments: 32 = 32 divisions vertically (smooth) */}
      <mesh position={[-0.8, 0, 0]}>
        <sphereGeometry args={[0.7, 32, 32]} />
        <meshStandardMaterial color="#10b981" />
      </mesh>

      {/* TorusGeometry - donut shape (built-in from Three.js)
          position: [0.8, 0, 0] = slightly to the right
          args: [radius, tube, radialSegments, tubularSegments]
          radius: 0.5 = distance from center to tube center
          tube: 0.15 = radius of the tube itself (thickness)
          radialSegments: 16 = segments around the tube
          tubularSegments: 100 = segments along the tube (very smooth) */}
      <mesh position={[0.8, 0, 0]}>
        <torusGeometry args={[0.5, 0.15, 16, 100]} />
        <meshStandardMaterial color="#8b5cf6" />
      </mesh>

      {/* CylinderGeometry - tube shape (built-in from Three.js)
          position: [2.5, 0, 0] = 2.5 units to the right
          args: [radiusTop, radiusBottom, height, radialSegments]
          radiusTop: 0.5 = top radius
          radiusBottom: 0.5 = bottom radius (same = cylinder, different = cone)
          height: 1 = height of the cylinder
          radialSegments: 32 = segments around the circle (smooth) */}
      <mesh position={[2.5, 0, 0]}>
        <cylinderGeometry args={[0.5, 0.5, 1, 32]} />
        <meshStandardMaterial color="#f59e0b" />
      </mesh>
    </group>
  );
}

'use client';

// Import useTexture hook from @react-three/drei
// drei is a collection of useful helpers for R3F
import { useTexture } from '@react-three/drei';

// Component function - demonstrates different material types
// Materials work on any geometry - here we use different shapes to show variety
function R3FMaterialsScene({ texturePath }: { texturePath: string }) {
  // useTexture is a hook that loads an image file as a texture
  // It handles loading, caching, and returns a THREE.Texture object
  // texturePath: string path to the image file (e.g., '/texture.jpg')
  // The hook automatically handles async loading and updates when path changes
  const texture = useTexture(texturePath);

  return (
    <group>
      {/* Basic material - flat color, no lighting
          meshBasicMaterial ignores all lights in the scene
          It always shows the same color regardless of lighting
          Useful for UI elements or unlit objects
          Using sphereGeometry to show materials work on any shape */}
      <mesh position={[-2, 0, 0]}>
        <sphereGeometry args={[0.7, 32, 32]} />
        <meshBasicMaterial color="#3b82f6" />
      </mesh>

      {/* Standard material with metallic properties
          meshStandardMaterial responds to lighting
          color: base color (can be a named color like 'gold')
          metalness: 0-1, how metallic (0.8 = very metallic, like gold)
          roughness: 0-1, how smooth (0.2 = very smooth, polished)
          Using torusGeometry (donut shape) to demonstrate variety */}
      <mesh position={[0, 0, 0]}>
        <torusGeometry args={[0.5, 0.2, 16, 100]} />
        <meshStandardMaterial
          color="gold"
          metalness={0.8}
          roughness={0.2}
        />
      </mesh>

      {/* Standard material with texture
          map: applies the texture loaded with useTexture
          The texture is applied on top of the base color
          The texture will be stretched to cover the entire surface
          color: still affects the final appearance (tints the texture)
          Using cylinderGeometry to show textures work on any geometry */}
      <mesh position={[2, 0, 0]}>
        <cylinderGeometry args={[0.5, 0.5, 1.5, 32]} />
        <meshStandardMaterial
          color="#8b5cf6"
          metalness={0.7}
          roughness={0.3}
          map={texture}
        />
      </mesh>
    </group>
  );
}

