import { useRef } from 'react';
// Import useFrame hook from R3F
import { useFrame } from '@react-three/fiber';
// Import THREE types
import * as THREE from 'three';

function AnimatedCube() {
  // 1. Create a reference to the mesh
  // We use useRef because modifying the DOM/Scene directly is faster
  // than triggering React re-renders for every frame (60fps)
  const meshRef = useRef<THREE.Mesh>(null);

  // 2. The useFrame hook runs on every single frame render
  // state: contains clock, mouse, viewport, etc.
  // delta: time since last frame (for smooth animation regardless of framerate)
  useFrame((state, delta) => {
    // Check if ref is attached
    if (meshRef.current) {
      // Rotate the mesh slightly every frame
      // Using delta ensures rotation speed is consistent on all devices
      meshRef.current.rotation.x += delta;
      meshRef.current.rotation.y += delta * 0.5;
    }
  });

  return (
    <mesh ref={meshRef}>
      <boxGeometry args={[2, 2, 2]} />
      <meshStandardMaterial color="orange" />
    </mesh>
  );
}

'use client';

import { useState } from 'react';

function InteractiveBox() {
  // Standard React state for interaction
  // These trigger a re-render when changed
  const [hovered, setHover] = useState(false);
  const [active, setActive] = useState(false);

  return (
    <mesh
      // Scale changes based on active state
      scale={active ? 1.5 : 1}
      // Event listeners work just like DOM elements (onClick, onPointerOver)
      onClick={() => setActive(!active)}
      onPointerOver={() => setHover(true)}
      onPointerOut={() => setHover(false)}
      // Change cursor to pointer to indicate interactivity
      onPointerEnter={() => document.body.style.cursor = 'pointer'}
      onPointerLeave={() => document.body.style.cursor = 'auto'}
    >
      <boxGeometry args={[1, 1, 1]} />
      {/* Color changes based on hover state */}
      <meshStandardMaterial 
        color={hovered ? 'hotpink' : 'orange'} 
        // visual feedback for cursor
      />
    </mesh>
  );
}

