// Import THREE.js for type safety
import * as THREE from 'three';

// Component function - a complete scene with geometry, material, and lighting
function R3FFirstScene() {
  return (
    {/* Fragment (<>...</>) groups multiple elements without adding a DOM node
        In R3F, this groups multiple 3D objects in the scene */}
    <>
      {/* The 3D object - a simple cube
          No position = centered at origin [0, 0, 0]
          args: [width, height, depth] = [2, 2, 2] = a 2x2x2 cube */}
      <mesh>
        <boxGeometry args={[2, 2, 2]} />
        {/* meshStandardMaterial with no props = default white material
            It will respond to lighting in the scene */}
        <meshStandardMaterial />
      </mesh>

      {/* Ambient light - soft overall illumination
          Provides base lighting to all objects equally
          Prevents pure black shadows (adds a base brightness)
          intensity: 0-1, how bright (0.1 = dim, prevents total darkness)
          Ambient light has no direction - it lights everything equally */}
      <ambientLight intensity={0.1} />

      {/* Directional light - like sunlight
          Shines from a specific direction, creates shadows and highlights
          position: [x, y, z] - direction the light comes from
                     [0, 0, 5] = light comes from in front (positive Z)
          color: color of the light ('red' = red-tinted light)
          intensity: 0-1, how bright (0.8 = quite bright)
          Directional lights create realistic lighting with highlights and shadows */}
      <directionalLight 
        position={[0, 0, 5]}
        color="red"
        intensity={0.8}
      />
    </>
  );
}

'use client';

// Import hooks and components from @react-three/drei
// OrbitControls: Camera control
// Environment: Realistic lighting
// ContactShadows: Faked ground shadows
import { useGLTF, useTexture, OrbitControls, Environment, ContactShadows } from '@react-three/drei';
import * as THREE from 'three';
import { useLayoutEffect } from 'react';

function ShowcaseScene({ texturePath }: { texturePath: string }) {
  // Load model and texture (as before)
  const { scene } = useGLTF('/beer2.gltf') as { scene: THREE.Group };
  const texture = useTexture(texturePath);

  useLayoutEffect(() => {
    if (!texture) return;
    texture.flipY = false;
    scene.traverse(obj => {
      if (obj instanceof THREE.Mesh && obj.material instanceof THREE.MeshStandardMaterial) {
        obj.material.map = texture;
        obj.material.needsUpdate = true;
        // Increase realism settings
        obj.material.envMapIntensity = 1.5;
        obj.material.roughness = 0.2;
        obj.material.metalness = 0.8;
      }
    });
  }, [scene, texture]);

  return (
    <group>
      {/* The 3D Model */}
      <primitive object={scene} dispose={null} position={[0, -1, 0]} />

      {/* OrbitControls: Allows the user to rotate/zoom the camera
          enableZoom: can turn off scrolling zoom if needed
          autoRotate: slowly spins the camera for presentation */}
      <OrbitControls autoRotate enableZoom={true} />

      {/* Environment: Loads a 360 HDRI map for realistic lighting/reflections
          preset: 'city', 'sunset', 'studio', etc. provides instant pro lighting */}
      <Environment preset="city" />

      {/* ContactShadows: Fakes realistic shadows on the ground without
          expensive raycasting calculations. Looks great for product showcases. */}
      <ContactShadows 
        position={[0, -1, 0]} 
        opacity={0.6} 
        scale={10} 
        blur={2} 
        far={4} 
      />
    </group>
  );
}
